// Stilisierte Produkt-Screens der EG-Plattform für die öffentliche Produktseite /energiegemeinschaften/software (T6).
// Reine Darstellung mit fiktiven, sichtbar als „Beispiel“ gekennzeichneten Werten – Aufbau wie im echten Portal
// (/portal/eg/[id], /portal/eg/[id]/abrechnung). Server-Komponenten ohne Hooks.
//
// Barrierefreiheit: Jeder Mock ist in sich geschlossen. Ohne `beschreibung` ist er rein dekorativ (aria-hidden),
// mit `beschreibung` ein Bild mit Alternativtext (role="img" + aria-label, Innenleben aria-hidden).
// Bewegung: keine Endlos-Animationen per Standard (WCAG 2.2.2). MockEnergieHeute bewegt sich nur mit `bewegt`;
// alle Effekte nutzen ausschließlich transform/opacity und sind unter prefers-reduced-motion still.

import { ArrowRight, BadgeCheck, BellRing, Check, Clock3, FileCheck2, GitCompareArrows, PiggyBank, Send, Sun, UsersRound } from "lucide-react";
import { cn } from "@/components/ui/cn";
import FortschrittsRing from "@/components/ui/FortschrittsRing";
import EnergieFluss from "@/components/Portal/EG/Mitglied/EnergieFluss";

/** Hülle: dekorativ (aria-hidden) oder – mit Beschreibung – ein Bild mit Alternativtext */
function BeispielBild({ beschreibung, className, children }) {
  if (beschreibung) {
    return (
      <div role="img" aria-label={beschreibung} className={className}>
        <div aria-hidden="true">{children}</div>
      </div>
    );
  }
  return <div aria-hidden="true" className={className}>{children}</div>;
}

/** Sichtbare Kennzeichnung fiktiver Werte (sun-700 auf sun-50 ≈ 6,4:1) */
function BeispielPlakette({ hell = false, className }) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center rounded-full font-semibold uppercase",
        hell
          ? "bg-white/10 px-1.5 py-px text-[9px] tracking-[0.14em] text-white/80 ring-1 ring-white/15"
          : "bg-sun-50 px-2 py-0.5 text-[10px] tracking-[0.12em] text-sun-700 ring-1 ring-sun-200",
        className
      )}
    >
      Beispiel
    </span>
  );
}

/** Browserfenster-Rahmen (ohne echte Adresse) */
export function FensterRahmen({ titel = "Plattform", beispiel = true, className, children }) {
  return (
    <div className={cn("overflow-hidden rounded-2xl bg-white shadow-e5 ring-1 ring-ink-200/80", className)}>
      <div className="flex items-center gap-2 border-b border-ink-100 bg-ink-50 px-3.5 py-2.5">
        <span className="flex w-14 shrink-0 gap-1.5" aria-hidden="true">
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
        </span>
        <span className="mx-auto min-w-0 truncate rounded-full bg-white px-3 py-0.5 text-[11px] font-medium text-ink-600 ring-1 ring-ink-200">{titel}</span>
        <span className="flex w-14 shrink-0 justify-end">{beispiel ? <BeispielPlakette /> : null}</span>
      </div>
      {children}
    </div>
  );
}

/** Telefon-Rahmen */
export function TelefonRahmen({ beispiel = true, className, children }) {
  return (
    <div className={cn("rounded-[2.4rem] bg-navy-950 p-2 shadow-e5 ring-1 ring-white/10", className)}>
      <div className="relative overflow-hidden rounded-[1.9rem]">
        <span aria-hidden="true" className="absolute left-1/2 top-2 z-10 h-1.5 w-16 -translate-x-1/2 rounded-full bg-white/15" />
        {beispiel ? <BeispielPlakette hell className="absolute right-4 top-1.5 z-10" /> : null}
        {children}
      </div>
    </div>
  );
}

const GRUEN = [
  { von: 10, bis: 15, stark: true },
  { von: 8.5, bis: 10, stark: false },
];
const JETZT = 12.5; // Uhrzeit der Jetzt-Marke (Beispiel)
const prozent = (h) => `${(h / 24) * 100}%`;

/** Mitglied: „Energie heute“ auf dem Handy */
export function MockEnergieHeute({ className, beschreibung, bewegt = false }) {
  return (
    <BeispielBild beschreibung={beschreibung} className={className}>
      <TelefonRahmen>
        <div className="ov-verlauf-nacht px-4 pb-5 pt-8 text-white">
          <p className="flex items-center gap-1.5 text-[10.5px] font-bold uppercase tracking-[0.16em] text-ov-300">
            {bewegt ? <span className="ov-live-punkt" /> : <span className="inline-block h-2 w-2 rounded-full bg-ov-400" />}
            Energie heute
          </p>
          <p className="mt-1 font-display text-[17px] font-extrabold leading-tight">Jetzt viel Gemeinschaftsstrom</p>
          <p className="mt-0.5 text-[11.5px] text-white/75">laut Prognose bis 15:00 Uhr</p>
          <div className="mt-4">
            <EnergieFluss gemeinschaftName="Sonnenland" ausGemeinschaft="212 kWh" aktiv={bewegt} kompakt />
          </div>
          <div className="mt-4 rounded-2xl bg-white/5 p-3.5 ring-1 ring-white/10">
            <p className="flex items-center gap-1.5 text-[11px] text-white/75"><PiggyBank aria-hidden="true" className="h-3.5 w-3.5 text-ov-300" />Ihre Ersparnis · dieses Jahr</p>
            <p className="ov-num font-display text-[30px] font-extrabold leading-tight tracking-tight">71,40<span className="ml-1 text-[16px] opacity-70">€</span></p>
            <div className="mt-2 flex items-center gap-3 border-t border-white/10 pt-2.5">
              <FortschrittsRing wert={38} groesse={46} staerke={5} ton="hell" dunkel sofort label="38 Prozent aus der Gemeinschaft" />
              <p className="text-[11px] leading-snug text-white/75">1.180 kWh kamen aus der Gemeinschaft</p>
            </div>
          </div>
          <div className="mt-3">
            <p className="mb-1.5 flex items-center gap-1 text-[11px] font-semibold text-white/85">
              <Sun aria-hidden="true" className="h-3 w-3 text-sun-300" />Grüne Stunden heute
              <span className="ml-auto font-medium text-white/70">10–15 Uhr</span>
            </p>
            <div className="relative h-4 rounded-full bg-white/10">
              {[6, 12, 18].map((h) => <span key={h} className="absolute inset-y-1 w-px bg-white/15" style={{ left: prozent(h) }} />)}
              {GRUEN.map((g) => (
                <span key={g.von} className={cn("absolute inset-y-0.5 rounded-full", g.stark ? "bg-ov-300" : "bg-ov-300/45")} style={{ left: prozent(g.von), width: prozent(g.bis - g.von) }} />
              ))}
              <span className="absolute -inset-y-0.5 w-0.5 -translate-x-1/2 rounded-full bg-white" style={{ left: prozent(JETZT) }} />
              <span className="absolute -top-1.5 h-1.5 w-1.5 -translate-x-1/2 rounded-full bg-white shadow-[0_0_8px_2px_rgba(255,255,255,0.5)]" style={{ left: prozent(JETZT) }} />
            </div>
            <div className="ov-num relative mt-1 h-3 text-[9.5px] font-medium text-white/70">
              <span className="absolute left-0">0</span>
              {[6, 12, 18].map((h) => <span key={h} className="absolute -translate-x-1/2" style={{ left: prozent(h) }}>{h}</span>)}
              <span className="absolute right-0">24 Uhr</span>
            </div>
          </div>
        </div>
      </TelefonRahmen>
    </BeispielBild>
  );
}

/** Mitglied: Zustimmung beim Netzbetreiber mit Fristring (dringend ab sieben Werktagen) und Anleitung */
export function MockZustimmung({ className, beschreibung, beispiel = true }) {
  const schritte = ["Kundenportal öffnen", "Bereich „Energiegemeinschaften“ wählen", "Anfrage der Gemeinschaft finden", "Teilnahmefaktor prüfen", "Zustimmen – erledigt"];
  const aktuell = 2;
  return (
    <BeispielBild beschreibung={beschreibung} className={className}>
      <FensterRahmen titel="Mein Beitritt · Zustimmung" beispiel={beispiel}>
        <div className="flex items-center gap-4 border-b border-sun-200 bg-sun-50 p-5">
          <FortschrittsRing wert={6} max={10} groesse={80} staerke={8} ton="warn" sofort label="Noch 6 Werktage für die Zustimmung">
            <span className="flex flex-col items-center leading-none">
              <span className="ov-num font-display text-[24px] font-extrabold text-ink-900">6</span>
              <span className="mt-0.5 text-[11px] font-semibold text-ink-600">Werktage</span>
            </span>
          </FortschrittsRing>
          <div className="min-w-0">
            <span className="inline-flex items-center gap-1 rounded-full bg-white px-2 py-0.5 text-[11px] font-bold text-sun-700 ring-1 ring-sun-200">
              <BellRing aria-hidden="true" className="h-3 w-3" />Dringend
            </span>
            <p className="mt-1.5 font-display text-[16px] font-bold leading-snug text-ink-900">Jetzt zustimmen – damit „Sonnenland“ Sie versorgen kann</p>
            <p className="mt-0.5 text-[12.5px] text-ink-600">Frist bis 14.10. · Anleitung für Ihren Netzbetreiber</p>
          </div>
        </div>
        <ol className="space-y-1.5 p-5">
          {schritte.map((s, i) => {
            const erledigt = i < aktuell;
            const jetzt = i === aktuell;
            return (
              <li key={s} className={cn("flex items-center gap-3 text-[13px]", jetzt ? "-mx-2 rounded-xl bg-navy-50/70 px-2 py-1.5 font-semibold text-ink-900" : "py-0.5 text-ink-700")}>
                <span
                  className={cn(
                    "flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[11px] font-bold",
                    erledigt ? "bg-ov-600 text-white" : jetzt ? "bg-white text-navy-700 ring-2 ring-navy-700" : "bg-white text-ink-600 ring-1 ring-ink-200"
                  )}
                >
                  {erledigt ? <Check aria-hidden="true" className="h-3.5 w-3.5" strokeWidth={3} /> : i + 1}
                </span>
                <span className={cn("min-w-0", erledigt && "text-ink-500 line-through decoration-ink-300")}>{s}</span>
                {erledigt && <span className="ml-auto shrink-0 text-[11px] font-semibold text-ov-700">erledigt</span>}
                {jetzt && (
                  <span className="ml-auto inline-flex shrink-0 items-center gap-0.5 text-[11px] font-semibold text-navy-700">
                    Jetzt<ArrowRight aria-hidden="true" className="h-3.5 w-3.5" />
                  </span>
                )}
              </li>
            );
          })}
        </ol>
      </FensterRahmen>
    </BeispielBild>
  );
}

const PIPELINE = ["Angelegt", "Vorschau", "1. Freigabe", "2. Freigabe", "Versendet", "Abgeschlossen"];

/**
 * Kassier: Abrechnungsperiode mit Status-Pipeline, Vergleich zum Vormonat und Vier-Augen-Freigabe.
 * Stand „Versendet“: beide Freigaben erteilt – passt zur Abschlussmeldung (MockAbschluss), die daneben gezeigt wird.
 */
export function MockKassier({ className, beschreibung, kompakt = false }) {
  const stand = 4;
  return (
    <BeispielBild beschreibung={beschreibung} className={className}>
      <FensterRahmen titel="Abrechnung · Oktober">
        <div className="space-y-4 p-4 md:p-5">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="font-display text-[15px] font-bold text-ink-900">Monat 01.10. – 31.10.</p>
            <span className="inline-flex items-center gap-1 rounded-full bg-navy-50 px-2.5 py-0.5 text-[11px] font-semibold text-navy-700 ring-1 ring-navy-100"><UsersRound aria-hidden="true" className="h-3 w-3" />Vier-Augen-Prinzip</span>
          </div>
          <div>
            <ol className="flex items-start">
              {PIPELINE.map((s, j) => (
                <li key={s} className="relative flex min-w-0 flex-1 flex-col items-center text-center">
                  {j > 0 && <span className={cn("absolute right-1/2 top-[11px] h-0.5 w-full", j <= stand ? "bg-ov-500" : "bg-ink-200")} />}
                  <span
                    className={cn(
                      "relative z-10 flex h-6 w-6 items-center justify-center rounded-full text-[11px] font-bold",
                      j < stand ? "bg-ov-600 text-white" : j === stand ? "bg-white text-navy-700 ring-2 ring-navy-700 ring-offset-2 ring-offset-white" : "bg-white text-ink-600 ring-1 ring-ink-200"
                    )}
                  >
                    {j < stand ? <Check aria-hidden="true" className="h-3 w-3" strokeWidth={3} /> : j + 1}
                  </span>
                  <span className={cn("mt-1.5 hidden text-[11px] leading-tight sm:block", j === stand ? "font-semibold text-ink-900" : "text-ink-600")}>{s}</span>
                </li>
              ))}
            </ol>
            <p className="mt-2 text-center text-[11px] text-ink-600 sm:hidden">
              Schritt {stand + 1} von {PIPELINE.length} · <span className="font-semibold text-ink-900">{PIPELINE[stand]}</span>
            </p>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {[["Rechnungen", "58", "4.212,80 €"], ["Gutschriften", "14", "1.906,30 €"], ["Vorteil Mitglieder", "", "1.084,10 €"]].map(([l, n, w]) => (
              <div key={l} className="rounded-xl bg-sand-50 p-2.5 ring-1 ring-sand-200">
                <p className="truncate text-[11px] text-ink-600">{l}</p>
                <p className="ov-num truncate text-[13px] font-bold text-ink-900">{n ? `${n} · ` : ""}{w}</p>
              </div>
            ))}
          </div>
          {!kompakt && (
            <div className="rounded-xl ring-1 ring-ink-200/70">
              <p className="flex items-center gap-1.5 border-b border-ink-100 px-3 py-2 text-[11.5px] font-semibold text-ink-800"><GitCompareArrows aria-hidden="true" className="h-3.5 w-3.5 text-ov-600" />Veränderung zum September · 3 auffällig</p>
              {[["Hofer, Landwirt", "+18 %", "neuer Zählpunkt"], ["Gemeindeamt", "−12 %", "Saison"], ["Familie Brandl", "neu dabei", ""]].map(([n, d, g]) => (
                <p key={n} className="flex items-center justify-between gap-2 border-t border-ink-100 px-3 py-1.5 text-[11.5px] first-of-type:border-t-0">
                  <span className="truncate text-ink-700">{n}{g ? <span className="text-ink-600"> · {g}</span> : null}</span>
                  <span className="shrink-0 rounded-full bg-sun-50 px-2 py-0.5 font-semibold text-sun-700 ring-1 ring-sun-200">{d}</span>
                </p>
              ))}
            </div>
          )}
          <div className="flex flex-wrap items-center gap-2">
            <span className="inline-flex items-center gap-1 rounded-full bg-ov-50 px-2.5 py-1 text-[11px] font-semibold text-ov-800 ring-1 ring-ov-200"><BadgeCheck aria-hidden="true" className="h-3 w-3" />Geprüft · Kassier</span>
            <span className="inline-flex items-center gap-1 rounded-full bg-ov-50 px-2.5 py-1 text-[11px] font-semibold text-ov-800 ring-1 ring-ov-200"><BadgeCheck aria-hidden="true" className="h-3 w-3" />Freigegeben · Vorstand</span>
            <span className="ml-auto inline-flex h-8 items-center gap-1.5 rounded-full bg-ov-600 px-3.5 text-[11.5px] font-semibold text-white shadow-gruen"><Send aria-hidden="true" className="h-3.5 w-3.5" />72 Belege versendet</span>
          </div>
        </div>
      </FensterRahmen>
    </BeispielBild>
  );
}

/** Abschlussmeldung des Kassier-Ablaufs */
export function MockAbschluss({ className, beschreibung }) {
  return (
    <BeispielBild beschreibung={beschreibung} className={className}>
      <div className="flex items-center gap-3 rounded-2xl bg-white p-3.5 shadow-e4 ring-1 ring-ink-200/70">
        <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-ov-600 text-white"><FileCheck2 aria-hidden="true" className="h-5 w-5" /></span>
        <p className="min-w-0 text-[12.5px] leading-snug text-ink-700"><strong className="block text-[13.5px] text-ink-900">72 Belege versendet</strong>Lastschrift am 05.11. – alles erledigt für Oktober</p>
      </div>
    </BeispielBild>
  );
}

/** Hero-Komposition: mobil Handy + Abschlussmeldung, ab sm Kassier-Fenster hinten, Handy vorn. Ohne Endlos-Bewegung. */
export function HeroKomposition({ className }) {
  return (
    <div
      role="img"
      aria-label="Beispielansicht der Plattform mit fiktiven Werten: Mitglied sieht auf dem Handy den Energiefluss und 71,40 € Ersparnis, der Kassier gibt die Oktober-Abrechnung im Vier-Augen-Prinzip frei."
      className={cn("relative isolate mx-auto w-full max-w-[680px]", className)}
    >
      {/* Ruhige Lichtquelle hinter den Geräten (statisch) */}
      <div aria-hidden="true" className="pointer-events-none absolute -inset-x-6 top-1/4 -z-10 h-2/3 rounded-full bg-ov-500/25 blur-[90px]" />
      <div aria-hidden="true" className="pointer-events-none absolute -bottom-10 right-0 -z-10 h-48 w-48 rounded-full bg-sun-400/15 blur-[80px]" />

      {/* Mobil: Handy zentral, Abschlussmeldung überlappt unten */}
      <div aria-hidden="true" className="relative sm:hidden">
        <div className="ov-hero-in mx-auto w-[72%] max-w-[260px]" style={{ "--ov-delay": "200ms" }}>
          <MockEnergieHeute />
        </div>
        <div className="ov-hero-in relative z-10 mx-auto -mt-10 w-[88%] max-w-[320px]" style={{ "--ov-delay": "380ms" }}>
          <MockAbschluss />
        </div>
      </div>

