// (/portal/eg/[id], /portal/eg/[id]/abrechnung). Server-Komponenten ohne Hooks.
//
// Barrierefreiheit: Jeder Mock ist in sich geschlossen. Ohne `beschreibung` ist er rein dekorativ (aria-hidden),
// mit `beschreibung` ein Bild mit Alternativtext (role="img" + aria-label, Innenleben aria-hidden).
// Bewegung: keine Endlos-Animationen per Standard (WCAG 2.2.2). MockEnergieHeute bewegt sich nur mit `bewegt`;
// alle Effekte nutzen ausschließlich transform/opacity und sind unter prefers-reduced-motion still.

import { ArrowRight, BadgeCheck, BellRing, Check, Clock3, FileCheck2, GitCompareArrows, PiggyBank, Send, Sun, UsersRound } from "lucide-react";
import { cn } from "@/components/ui/cn";
import FortschrittsRing from "@/components/ui/FortschrittsRing";
import EnergieFluss from "@/components/Portal/EG/Mitglied/EnergieFluss";

/** Hülle: dekorativ (aria-hidden) oder – mit Beschreibung – ein Bild mit Alternativtext */
function BeispielBild({ beschreibung, className, children }) {
  if (beschreibung) {
    return (
      <div role="img" aria-label={beschreibung} className={className}>
        <div aria-hidden="true">{children}</div>
      </div>
    );
  }
  return <div aria-hidden="true" className={className}>{children}</div>;
}

/** Sichtbare Kennzeichnung fiktiver Werte (sun-700 auf sun-50 ≈ 6,4:1) */
function BeispielPlakette({ hell = false, className }) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center rounded-full font-semibold uppercase",
        hell
          ? "bg-white/10 px-1.5 py-px text-[9px] tracking-[0.14em] text-white/80 ring-1 ring-white/15"
          : "bg-sun-50 px-2 py-0.5 text-[10px] tracking-[0.12em] text-sun-700 ring-1 ring-sun-200",
        className
      )}
    >
      Beispiel
    </span>
  );
}

/** Browserfenster-Rahmen (ohne echte Adresse) */
export function FensterRahmen({ titel = "Plattform", beispiel = true, className, children }) {
  return (
    <div className={cn("overflow-hidden rounded-2xl bg-white shadow-e5 ring-1 ring-ink-200/80", className)}>
      <div className="flex items-center gap-2 border-b border-ink-100 bg-ink-50 px-3.5 py-2.5">
        <span className="flex w-14 shrink-0 gap-1.5" aria-hidden="true">
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
          <span className="h-2.5 w-2.5 rounded-full bg-ink-200" />
        </span>
        <span className="mx-auto min-w-0 truncate rounded-full bg-white px-3 py-0.5 text-[11px] font-medium text-ink-600 ring-1 ring-ink-200">{titel}</span>
        <span className="flex w-14 shrink-0 justify-end">{beispiel ? <BeispielPlakette /> : null}</span>
      </div>
      {children}
    </div>
  );
}

/** Telefon-Rahmen */
export function TelefonRahmen({ beispiel = true, className, children }) {
  return (
    <div className={cn("rounded-[2.4rem] bg-navy-950 p-2 shadow-e5 ring-1 ring-white/10", className)}>
      <div className="relative overflow-hidden rounded-[1.9rem]">
        <span aria-hidden="true" className="absolute left-1/2 top-2 z-10 h-1.5 w-16 -translate-x-1/2 rounded-full bg-white/15" />
        {beispiel ? <BeispielPlakette hell className="absolute right-4 top-1.5 z-10" /> : null}
        {children}
      </div>
    </div>
  );
}

